{
  "assessment": "As Prime Minister, my foremost duty is to secure the territorial integrity and prosperity of Somalia. Al-Shabaab continues to hold Jubbada Dhexe, threatening our national unity. To effectively combat this insurgency and stabilise our economy, we must bolster our military posture while maintaining internal security. We will scale up military spending and infrastructure investment, deploy forces to pressure the insurgency, and initiate diplomatic outreach to key allies.",
  "directives": [
    {
      "type": "set_spending",
      "target": null,
      "amount": 3.0,
      "sub": "military",
      "order": "Increase military spending to 3.0 percent of GDP to strengthen our armed forces against al-Shabaab."
    },
    {
      "type": "invest_infrastructure",
      "target": null,
      "amount": 2.0,
      "sub": "",
      "order": "Invest an additional 2 percent of GDP into infrastructure to support economic growth and regional integration."
    },
    {
      "type": "military_mobilize",
      "target": null,
      "amount": 0.2,
      "sub": "",
      "order": "Mobilize 20 percent of military reserves to build sufficient force concentration for offensive operations."
    },
    {
      "type": "military_deploy",
      "target": "SOM",
      "amount": 0,
      "sub": "",
      "order": "Deploy forces to the border of Jubbada Dhexe in preparation for operations against al-Shabaab."
    }
  ],
  "cables": [
    {
      "to": "EGY",
      "private": true,
      "text": "The Government of Somalia seeks to deepen strategic and military cooperation with Egypt in our ongoing efforts to eradicate al-Shabaab and secure the Horn of Africa."
    }
  ],
  "public_statement": "The Federal Government of Somalia remains steadfast in its commitment to eliminating terrorist elements, restoring full sovereignty over all national territory, and driving sustainable economic development for all Somalis.",
  "standing_orders": [
    {
      "when": "at_war",
      "do": {
        "type": "repression_level",
        "target": null,
        "amount": 0.5,
        "sub": "",
        "order": "Maintain moderate internal security posture during active military engagements."
      }
    }
  ],
  "detailed_report": "military"
}
